// Filter for stories with 'action' in subject
const items = $input.all();
const filtered = [];

for (const item of items) {
  const story = item.json;
  if (story.subject && story.subject.toLowerCase().includes('action')) {
    // Check if created in last 2 minutes
    const created = new Date(story.created_date);
    const now = new Date();
    const diffMinutes = (now - created) / (1000 * 60);

    if (diffMinutes <= 2) {
      filtered.push({
        json: {
          originalId: story.id,
          projectId: story.project,
          title: story.subject,
          ref: story.ref,
          assignedTo: story.assigned_to
        }
      });
    }
  }
}

return filtered;
